   776  static enum lwan_http_status
   777  read_from_request_socket(struct lwan_request *request,
   778                           struct lwan_value *buffer,
   779                           const size_t buffer_size,
   780                           enum lwan_read_finalizer (*finalizer)(
   781                               size_t total_read,
   782                               size_t buffer_size,
   783                               struct lwan_request *request,
   784                               int n_packets))
   785  {
   786      struct lwan_request_parser_helper *helper = request->helper;
   787      ssize_t n;
   788      size_t total_read = 0;
   789      int n_packets = 0;
   790
   791      if (helper->next_request) {
   792          const size_t next_request_len = (size_t)(helper->next_request - buffer->value);
   793          size_t new_len;
   794
   795          if (__builtin_sub_overflow(buffer->len, next_request_len, &new_len)) {
   796              helper->next_request = NULL;
   797          } else {
   798              /* FIXME: This memmove() could be eventually removed if a better
   799               * stucture were used for the request buffer. */
   800              buffer->len = new_len;
   801              memmove(buffer->value, helper->next_request, buffer->len);
   802              total_read = buffer->len;
   803              goto try_to_finalize;
   804          }
   805      }
   806
   807      for (;; n_packets++) {
   808          n = read(request->fd, buffer->value + total_read,
   809                   (size_t)(buffer_size - total_read - 1));
   810          /* Client has shutdown orderly, nothing else to do; kill coro */
   811          if (UNLIKELY(n == 0)) {
   812              coro_yield(request->conn->coro, CONN_CORO_ABORT);
   813              __builtin_unreachable();
   814          }
   815
   816          if (UNLIKELY(n < 0)) {
   817              switch (errno) {
   818              case EAGAIN:
   819                  request->conn->flags |= CONN_FLIP_FLAGS;
   820                  coro_yield(request->conn->coro, CONN_CORO_MAY_RESUME);
   821                  /* fallthrough */
   822              case EINTR:
   823  yield_and_read_again:
   824                  request->conn->flags |= CONN_MUST_READ;
   825                  coro_yield(request->conn->coro, CONN_CORO_MAY_RESUME);
   826                  continue;
   827              }
   828
   829              /* Unexpected error before reading anything */
   830              if (UNLIKELY(!total_read))
   831                  return HTTP_BAD_REQUEST;
   832
   833              /* Unexpected error, kill coro */
   834              coro_yield(request->conn->coro, CONN_CORO_ABORT);
   835              __builtin_unreachable();
   836          }
   837
   838          total_read += (size_t)n;
   839          buffer->len = (size_t)total_read;
   840
   841  try_to_finalize:
   842          switch (finalizer(total_read, buffer_size, request, n_packets)) {
   843          case FINALIZER_DONE:
   844              request->conn->flags &= ~CONN_MUST_READ;
   845              buffer->value[buffer->len] = '\0';
   846
   847  #if defined(FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION)
   848              save_to_corpus_for_fuzzing(buffer);
   849  #endif
   850
   851              return HTTP_OK;
   852
   853          case FINALIZER_TRY_AGAIN:
   854              continue;
   855
   856          case FINALIZER_YIELD_TRY_AGAIN:
   857              goto yield_and_read_again;
   858
   859          case FINALIZER_ERROR_TOO_LARGE:
   860              return HTTP_TOO_LARGE;
   861
   862          case FINALIZER_ERROR_TIMEOUT:
   863              return HTTP_TIMEOUT;
   864          }
   865      }
   866
   867      /* Shouldn't reach here. */
   868      coro_yield(request->conn->coro, CONN_CORO_ABORT);
   869      __builtin_unreachable();
   870      return HTTP_INTERNAL_ERROR;
   871  }
